const L = wall_length, H = height, T = thickness, nw = Math.round(windows), bays = nw + (door ? 1 : 0);
const z = addpoint(0, [0, 0, 0]);
for (const g of ['cut', 'win_at', 'door_at']) setpointgroup(0, g, z, 0);
if (!bays) return;
const bw = L / bays, dbay = door ? Math.floor(bays / 2) : -1;
const ww = Math.min(window_width, bw - 0.2), sill = Math.min(sill_height, H - 0.45), wh = Math.min(window_height, H - sill - 0.15);
const dw = Math.min(1, bw - 0.2), dh = Math.min(2.1, H - 0.15);
for (let i = 0; i < bays; i++) {
  const x = bw * (i + 0.5), isDoor = i === dbay;
  if ((isDoor ? dw : ww) <= 0.05 || (isDoor ? dh : wh) <= 0.05) continue;
  const c = addpoint(0, isDoor ? [x, (dh - 0.05) / 2, 0] : [x, sill + wh / 2, 0]);
  setpointattrib(0, 'scale', c, isDoor ? [dw, dh + 0.05, T + 0.2] : [ww, wh, T + 0.2]);
  setpointgroup(0, 'cut', c, 1);
  const a = addpoint(0, [x, isDoor ? 0 : sill, 0]);
  setpointgroup(0, isDoor ? 'door_at' : 'win_at', a, 1);
}
